# -*- coding: utf-8 -*-
# (speaker, italiano, coreano); speaker None => didascalia, "#" => titolo di scena (nessuno dei due conta come battuta)
F, R, L, G, M, C, GI = "Filippo", "Renzo", "Lorenzo", "Graziella", "Matteo", "Chiara", "Giulia"
D = [
("#", "Scena 1 — Venerdì 12 dicembre, ore 7.15. Il laboratorio di Scandicci, ancora vuoto.", "장면 1 — 12월 12일 금요일 오전 7시 15분. 아직 비어 있는 스칸디치 공방."),
(None, "Le luci della corsia centrale sono accese solo a metà. Filippo è in piedi davanti alla bacheca dove è appesa, incorniciata, la fotocopia della lettera di Ugo. Ha in mano un foglio piegato in quattro. Renzo entra con il thermos e la fascia elastica al polso.", "가운데 통로 조명은 절반만 켜져 있다. 필리포는 우고의 편지 복사본을 액자에 넣어 걸어 둔 게시판 앞에 서 있다. 손에는 네 번 접은 종이 한 장. 렌초가 보온병을 들고 손목에 탄력 밴드를 찬 채 들어온다."),
(R, "Filippo. A quest'ora qui ci sono solo io e i topi. E i topi sono in pensione.", "필리포. 이 시간엔 여기 나랑 쥐들밖에 없는데. 쥐들도 은퇴했고."),
(F, "Non riuscivo a dormire. Stasera la mamma ci vuole tutti a cena. Con Lorenzo e con i libri sociali.", "잠이 안 와서요. 오늘 저녁에 엄마가 다 모이래요. 로렌초랑 회사 장부까지 들고."),
(R, "Allora stasera si decide chi si siede a capotavola.", "그럼 오늘 저녁에 누가 상석에 앉을지 정하는구나."),
(F, "Lo sanno tutti chi si siede a capotavola. Il maggiore. Lo dicono anche i fornitori: « Quando comanderà il dottor Filippo… »", "누가 상석에 앉을지는 다들 알아요. 맏이죠. 납품업자들까지 그래요. '필리포 사장님이 맡으시면…'"),
(R, "E tu che cosa dici?", "그럼 너는 뭐라고 하는데?"),
(F, "Io ho scritto una cosa stanotte. (mostra il foglio) Ma prima di leggerla stasera, la volevo leggere a qualcuno che non è della famiglia.", "어젯밤에 뭘 좀 썼어요. (종이를 보여 주며) 그런데 오늘 저녁 읽기 전에, 가족 아닌 사람한테 먼저 읽어 주고 싶었어요."),
(R, "Io non sono della famiglia da cinquantanove anni. Leggi.", "난 59년째 가족 아닌 사람이지. 읽어 봐."),
(F, "No. Prima una domanda. Il nonno Ugo era uno che partiva o uno che teneva la porta?", "아니요. 먼저 하나만 물을게요. 우고 할아버지는 떠나는 사람이었어요, 문을 지키는 사람이었어요?"),
(R, "Il signor Ugo? Partiva. Partiva sempre. A Milano, a Parigi, alle fiere con la valigia di cartone. La porta la teneva tua nonna, la sua signora.", "우고 사장님? 떠나셨지. 늘 떠나셨어. 밀라노로, 파리로, 판지 가방 들고 박람회로. 문은 네 할머니, 사장님 부인께서 지키셨고."),
(F, "E il babbo?", "그럼 아빠는요?"),
(R, "Tuo padre voleva partire, ma teneva la porta. Per questo era sempre stanco. Faceva due mestieri e ne amava uno solo.", "네 아버지는 떠나고 싶어 했지만 문을 지켰어. 그래서 늘 지쳐 있었지. 일을 두 가지 하면서 하나만 사랑했으니까."),
(F, "Quale?", "어느 쪽을요?"),
(R, "Quello che faceva meno. (beve dal thermos) E tu, Filippo? Quale ami?", "덜 하던 쪽. (보온병에서 한 모금 마신다) 그럼 너는, 필리포? 너는 어느 쪽을 사랑하니?"),
(F, "Io amo i conti che tornano, le banche che rispondono al telefono, i contratti senza sorprese. Amo che la gente arrivi alle otto e trovi le luci accese.", "저는 맞아떨어지는 장부를 사랑해요. 전화 받는 은행, 놀랄 일 없는 계약서. 사람들이 8시에 와서 불이 켜져 있는 걸 보는 게 좋아요."),
(R, "Allora sai già che cosa c'è scritto su quel foglio.", "그럼 그 종이에 뭐라고 썼는지 이미 알고 있구나."),
(F, "Lo so. Ho paura di come lo prenderà Matteo. E di come lo prenderà la gente. « Il fratello maggiore che si fa da parte. »", "알아요. 마테오가 어떻게 받아들일지 겁나요. 사람들이 어떻게 볼지도요. '물러나는 맏형.'"),
(R, "Farsi da parte e tenere la porta non sono la stessa cosa. Chi si fa da parte esce dalla stanza. Chi tiene la porta resta lì, e tutti gli passano davanti.", "물러나는 것과 문을 지키는 건 같지 않아. 물러나는 사람은 방을 나가지. 문을 지키는 사람은 거기 남고, 모두가 그 앞을 지나가고."),
(F, "E nessuno lo ringrazia.", "그리고 아무도 고마워하지 않죠."),
(R, "Io ringraziavo tua nonna tutte le mattine. E ringrazio te da quando sei tornato da Milano. Non te l'ho mai detto, perché non serviva.", "나는 네 할머니께 매일 아침 고맙다고 했어. 그리고 네가 밀라노에서 돌아온 뒤로 너한테도 고마워했지. 말한 적은 없어. 할 필요가 없었으니까."),
(F, "(piega il foglio) Grazie, Renzo.", "(종이를 접으며) 고마워요, 렌초."),
(R, "Adesso vai a casa e dormi un'ora. Un presidente con le occhiaie non convince nessuno.", "이제 집에 가서 한 시간만 자. 다크서클 낀 회장은 아무도 설득 못 한다."),
(F, "Non ho ancora detto che sarò presidente.", "아직 회장 하겠다고 말한 적 없어요."),
(R, "Me l'hai detto alle sette e un quarto, venendo qui al buio. Il resto sono parole.", "7시 15분에 깜깜한데 여기 온 걸로 이미 말했어. 나머진 말일 뿐이야."),

("#", "Scena 2 — Ore 19.30. Casa Corsini, la tavola della domenica, di venerdì.", "장면 2 — 오후 7시 30분. 코르시니 가, 금요일의 일요일 식탁."),
(None, "Sulla tavola non c'è la tovaglia a quadri ma quella bianca delle feste. Al posto della zuppiera, il libro dei verbali rilegato in tela verde e il timbro di Ugo nella sua scatola di latta. Lorenzo, con il computer portatile, siede in fondo. Giulia porta il vino e resta sulla soglia della cucina.", "식탁엔 체크무늬 식탁보가 아니라 명절용 흰 식탁보가 깔렸다. 수프 그릇 자리에는 초록 천으로 제본한 의사록 장부와 양철 상자에 든 우고의 도장. 로렌초가 노트북을 들고 끝자리에 앉는다. 줄리아는 포도주를 내오고 부엌 문턱에 서 있다."),
(G, "A gennaio, a questa tavola, vi ho detto: « Non me la trasformate in un consiglio di amministrazione. » Stasera la trasformo io. Per una sera sola.", "1월에 이 식탁에서 너희한테 말했지. '이 식탁을 이사회로 만들지 마라.' 오늘 밤엔 내가 만든다. 딱 하룻저녁만."),
(L, "Signora, per il verbale: assemblea totalitaria dei soci, tutti presenti. Ore diciannove e trentadue.", "여사님, 의사록을 위해 말씀드립니다. 전원 출석 주주총회입니다. 오후 7시 32분."),
(G, "Grazie, Lorenzo. Allora comincio io, che sono la più vecchia. Io lascio la presidenza.", "고마워요, 로렌초. 그럼 제일 나이 많은 내가 시작하지. 나는 회장 자리에서 물러난다."),
(C, "Mamma...", "엄마…"),
(G, "Lasciatemi finire. Non me ne vado da nessuna parte. Resto in consiglio fino all'assemblea di primavera, e poi, se mi volete, presidente onoraria. Vale a dire: vengo alle feste, assaggio le borse nuove e non firmo più niente.", "끝까지 말하게 해 줘. 어디 가는 거 아니야. 봄 주주총회까지는 이사회에 남고, 그다음엔 너희가 원하면 명예회장. 다시 말해 파티에 오고, 새 가방을 맛보고, 더는 아무것도 서명하지 않는다는 거지."),
(M, "Assaggi le borse?", "가방을 맛본다고요?"),
(G, "Le annuso. Quarant'anni di pelle: sento il tannino meglio di Renzo.", "냄새를 맡지. 가죽 40년이면 렌초보다 탄닌을 더 잘 맡아."),
(M, "Questo non lo dire a Renzo.", "그건 렌초한테 말하지 마세요."),
(G, "Gliel'ho già detto. Ha riso. (si siede) Adesso tocca a voi. Il consiglio lo nominate voi, come soci. E il consiglio nomina il presidente e l'amministratore delegato.", "벌써 했어. 웃더라. (자리에 앉으며) 이제 너희 차례야. 이사회는 너희가 주주로서 선임해. 그리고 이사회가 회장과 대표이사를 선임하고."),
(L, "La proposta per il consiglio è di cinque membri: la signora Graziella, Filippo, Chiara, Matteo. E il quinto…", "이사회 안은 다섯 명입니다. 그라치엘라 여사님, 필리포, 키아라, 마테오. 그리고 다섯 번째는…"),
(G, "Il quinto è lei, Lorenzo. Non faccia quella faccia. Ventinove anni di bilanci valgono un posto a tavola.", "다섯 번째는 당신이에요, 로렌초. 그런 얼굴 하지 말아요. 29년 결산이면 식탁에 한 자리 받을 만해요."),
(L, "Signora, io sono un dipendente.", "여사님, 저는 직원입니다."),
(F, "Proprio per questo. Ci serve qualcuno che vota senza essere nostro fratello.", "바로 그래서예요. 우리 형제가 아니면서 표를 던질 사람이 필요해요."),
(L, "(si schiarisce la voce) Accetto. Ma il verbale lo scrivo lo stesso io.", "(헛기침을 하며) 수락하겠습니다. 하지만 의사록은 그래도 제가 씁니다."),
(G, "Allora, chi vota per questo consiglio?", "자, 이 이사회 안에 찬성하는 사람?"),
(C, "Io.", "나."),
(M, "Io.", "저도요."),
(F, "Io.", "저도."),
(G, "E io. All'unanimità. Lorenzo, scriva. Ora siete in consiglio. E il consiglio deve dire chi fa il presidente.", "나도. 만장일치. 로렌초, 적어요. 이제 너희가 이사회야. 그리고 이사회는 누가 회장을 할지 말해야 해."),
(None, "Silenzio. Chiara guarda Filippo. Matteo guarda Filippo. Anche Giulia, dalla soglia, guarda suo padre. Filippo tira fuori il foglio piegato in quattro e non lo apre.", "침묵. 키아라가 필리포를 본다. 마테오도 필리포를 본다. 문턱에 선 줄리아도 아빠를 본다. 필리포는 네 번 접은 종이를 꺼내지만 펴지 않는다."),
(M, "Fili, è inutile che facciamo finta. Il presidente sei tu. E l'amministratore delegato pure. Hai tenuto in piedi l'azienda con Varenne, con le borse false, con la Maison ad agosto. Chi altro?", "형, 모르는 척해 봐야 소용없어. 회장은 형이야. 대표이사도. 바렌 때도, 가짜 가방 때도, 8월 메종 때도 형이 회사를 버텨 냈잖아. 누가 또 있어?"),
(F, "Io il presidente lo faccio. L'amministratore delegato no.", "회장은 내가 할게. 대표이사는 안 해."),
(M, "Come no?", "안 한다니?"),
(F, "L'amministratore delegato lo fai tu.", "대표이사는 네가 해."),
(M, "(ride, poi smette) Stai scherzando.", "(웃다가 멈춘다) 농담하는 거지."),
(F, "Ti sembro uno che scherza alle sette e mezza di sera con la tovaglia bianca?", "흰 식탁보 깔고 저녁 7시 반에 농담하는 사람처럼 보여?"),
(C, "Filippo, aspetta. Spiegaci. Perché da gennaio fai tutto tu, il budget, le banche, il patto, i fornitori. E adesso lo lasci a Matteo?", "필리포, 잠깐. 설명해 봐. 1월부터 예산, 은행, 협약, 납품업체 전부 오빠가 했잖아. 그런데 이제 그걸 마테오한테 넘긴다고?"),
(F, "Non lo lascio. Lo divido. Leggo una cosa, se me lo permettete. L'ho scritta stanotte e l'ho letta a Renzo stamattina.", "넘기는 게 아니라 나누는 거야. 괜찮으면 하나 읽을게. 어젯밤에 썼고 오늘 아침 렌초한테 읽어 줬어."),
(G, "Leggi.", "읽어 봐."),
(F, "(apre il foglio) « Il nonno ha scritto: servono tutti e due, chi parte e chi tiene la porta aperta. Io quest'anno ho capito una cosa che a quarantaquattro anni è difficile da dire: io sono quello che tiene la porta. »", "(종이를 편다) '할아버지는 쓰셨다. 둘 다 필요하다, 떠나는 사람도 문을 열어 두는 사람도. 나는 올해 마흔넷에 말하기 어려운 걸 하나 깨달았다. 나는 문을 지키는 사람이다.'"),
(G, "(piano) Vai avanti.", "(조용히) 계속해."),
(F, "« Matteo è quello che parte. È partito per Seul, per Tokyo, per New York, e ogni volta è tornato con un ordine e con una storia. Un'azienda che vuole vivere altri settant'anni ha bisogno che a guidarla sia chi parte. E che chi tiene la porta non gliela chiuda mai alle spalle. »", "'마테오는 떠나는 사람이다. 서울로, 도쿄로, 뉴욕으로 떠났고, 매번 주문서와 이야기를 들고 돌아왔다. 70년을 더 살고 싶은 회사라면 떠나는 사람이 이끌어야 한다. 그리고 문을 지키는 사람은 그의 등 뒤에서 문을 절대 닫지 말아야 한다.'"),
(None, "Il foglio trema appena. Filippo lo ripiega. Nessuno parla. Graziella si porta il tovagliolo alla bocca.", "종이가 살짝 떨린다. 필리포가 다시 접는다. 아무도 말이 없다. 그라치엘라가 냅킨을 입에 갖다 댄다."),
(M, "Fili, io ho trentun anni. Un anno fa stavo per mandare una mail a Seul e impegnare l'azienda da solo, senza la firma di nessuno.", "형, 나 서른한 살이야. 1년 전엔 누구 서명도 없이 혼자 회사를 걸고 서울에 메일을 보내려던 사람이라고."),
(F, "E non l'hai mandata. Hai tolto il dito dal tasto e mi hai telefonato. È per quella telefonata che ti voto.", "그런데 안 보냈잖아. 버튼에서 손가락 떼고 나한테 전화했지. 그 전화 때문에 너한테 표를 주는 거야."),
(M, "E se non sono all'altezza?", "그런데 내가 감당할 수 없으면?"),
(F, "Allora te lo dico io. È questo il lavoro del presidente: dire all'amministratore delegato quando non è all'altezza. In privato, e mai davanti ai clienti.", "그럼 내가 말해 줄게. 그게 회장 일이야. 대표이사가 감당 못 할 때 그렇게 말해 주는 거. 단둘이 있을 때, 손님들 앞에선 절대 말고."),
(C, "E io? Scusate, ma lo devo chiedere. Io resto la sorella di mezzo che disegna?", "그럼 나는? 미안하지만 물어봐야겠어. 난 계속 그림 그리는 둘째 딸이야?"),
(F, "Tu resti direttrice creativa, e sei in consiglio con diritto di voto pieno. Nessuna collezione, nessun negozio, nessun marchio nuovo senza il tuo sì. L'ho scritto in fondo al foglio.", "넌 크리에이티브 디렉터로 남고, 의결권을 온전히 가진 이사야. 네가 찬성하지 않으면 컬렉션도, 매장도, 새 브랜드도 없어. 종이 맨 끝에 적어 놨어."),
(C, "Fammi vedere. (legge) « Ne va del nome. Il nome lo disegna Chiara. » (pausa) Va bene. Ma non chiamarmi più « la sorella di mezzo ».", "보여 줘. (읽는다) '이름이 걸린 일이다. 이름은 키아라가 그린다.' (잠시 뒤) 좋아. 하지만 다시는 '둘째 딸'이라고 부르지 마."),
(M, "Sei tu che ti chiami così, Chiara.", "누나가 스스로 그렇게 부르잖아, 키아라."),
(C, "Appunto. Smetto da stasera.", "그러니까. 오늘 밤부터 그만할게."),
(M, "Fili, un'ultima cosa. Se il presidente tiene la porta, chi decide quando qualcuno vuole entrare? Come Omar a ottobre.", "형, 마지막으로 하나만. 회장이 문을 지킨다면, 누가 들어오려고 할 때는 누가 정해? 10월의 오마르처럼."),
(F, "Il presidente. A ottobre Omar voleva il trenta per cento e io ho detto di no. Questo è tenere la porta: dalla porta si entra per comprare borse, non per comprare noi.", "회장이 정하지. 10월에 오마르는 30%를 원했고 나는 거절했어. 그게 문을 지키는 거야. 그 문으로는 가방을 사러 들어오는 거지, 우리를 사러 들어오는 게 아니야."),
(M, "Ma il contratto con Sahar l'ho chiuso io. Dubai, Doha, Kuwait City, Riad.", "그래도 사하르 계약은 내가 따냈어. 두바이, 도하, 쿠웨이트시티, 리야드."),
(F, "Appunto. Tu porti dentro i clienti, io tengo fuori i soci. Quattro negozi nel Golfo e nessuna quota venduta: è il lavoro di due persone.", "그러니까. 너는 손님을 들이고, 나는 동업자를 막아. 걸프에 매장 넷, 팔린 지분은 없음. 그게 두 사람이 하는 일이야."),
(C, "E i mobili di quei quattro negozi li disegno io. Consegna a novembre, e sono già in ritardo di dieci giorni.", "그리고 그 네 매장 가구는 내가 디자인하지. 11월 마감인데 벌써 열흘 늦었어."),
(F, "Lo so. Lorenzo l'ha scritto sul foglio del lunedì.", "알아. 로렌초가 월요일 보고서에 적었더라."),
(L, "In rosso, Chiara. Come sempre.", "빨간 글씨로요, 키아라. 늘 그렇듯이."),
(M, "Il foglio del lunedì. Anche quello è tenere la porta.", "월요일 보고서라. 그것도 문을 지키는 거네."),
(G, "Lorenzo, adesso la parte noiosa. Ma la dica bene, che la sentano tutti.", "로렌초, 이제 지루한 부분이에요. 그래도 제대로 말해 줘요, 다들 듣게."),
(L, "Proposta del consiglio. Primo: Filippo Corsini presidente del consiglio di amministrazione, con la rappresentanza legale, i rapporti con le banche, con i soci e con i legali.", "이사회 안건. 첫째, 필리포 코르시니를 이사회 회장으로. 법적 대표권, 은행·주주·법률 자문과의 관계를 맡습니다."),
(C, "« Con i legali » vuol dire con Mancini. Auguri, Filippo.", "'법률 자문'이란 건 만치니 얘기네. 행운을 빌어, 오빠."),
(F, "Mancini mi chiama già alle sette di mattina. Niente di nuovo.", "만치니는 벌써 아침 7시에 전화해. 새로울 거 없어."),
(L, "Secondo: Matteo Corsini amministratore delegato, con tutte le deleghe operative: commerciale, export, produzione, personale. Firma fino a cinquecentomila euro; sopra, con il presidente.", "둘째, 마테오 코르시니를 대표이사로. 영업, 수출, 생산, 인사 등 모든 업무 권한을 위임합니다. 50만 유로까지 단독 서명, 그 이상은 회장과 공동 서명."),
(M, "Cinquecentomila? Ad agosto firmavo fino a centomila e mi tremava la mano.", "50만? 8월엔 10만까지 서명하는데도 손이 떨렸는데."),
(F, "Ti tremerà ancora. Tanto più che adesso firmi anche gli stipendi. È giusto che tremi.", "앞으로도 떨릴 거야. 더구나 이제 월급까지 네가 서명하니까. 떨리는 게 맞아."),
(L, "Terzo: Chiara Corsini consigliere e direttrice creativa, con parere vincolante su collezioni, punti vendita e marchio. Quarto: la signora Graziella presidente onoraria dall'assemblea di primavera.", "셋째, 키아라 코르시니를 이사 겸 크리에이티브 디렉터로. 컬렉션, 매장, 상표에 대해 구속력 있는 의견권을 갖습니다. 넷째, 그라치엘라 여사님을 봄 주주총회부터 명예회장으로."),
(G, "Dalla primavera. Prima voglio vedere come ve la cavate.", "봄부터야. 그 전에 너희가 어떻게 해 나가는지 보고 싶어."),
(L, "Quinto: tutte le nomine hanno effetto da lunedì ventinove dicembre.", "다섯째, 모든 선임은 12월 29일 월요일부터 효력을 갖습니다."),
(C, "Perché il ventinove e non subito?", "왜 29일이야? 지금 바로가 아니고?"),
(G, "Perché prima c'è Natale. E a Natale il capotavola sono ancora io.", "그 전에 성탄절이 있으니까. 성탄절엔 아직 내가 상석이야."),
(F, "Si vota. Chi è favorevole?", "표결합니다. 찬성하는 사람?"),
(None, "Cinque mani. Matteo alza la sua per ultimo, lentamente, come se pesasse.", "다섯 개의 손. 마테오가 마지막으로, 무게라도 있는 듯 천천히 손을 든다."),
(L, "Unanimità. Ore venti e diciassette. Il verbale lo firmano il presidente e il segretario.", "만장일치. 오후 8시 17분. 의사록은 회장과 서기가 서명합니다."),
(G, "Il presidente uscente, Lorenzo. Per altre due settimane. (firma)", "퇴임하는 회장이죠, 로렌초. 앞으로 2주 더. (서명한다)"),
(GI, "(dalla soglia) Posso applaudire, o è vietato dal verbale?", "(문턱에서) 박수 쳐도 돼? 아니면 의사록에서 금지야?"),
(L, "Il verbale non lo vieta, signorina.", "의사록에 금지 조항은 없습니다, 아가씨."),
(None, "Giulia applaude da sola, poi Chiara, poi tutti. Graziella si alza e va in cucina. Torna con la zuppa inglese.", "줄리아가 혼자 박수를 치고, 키아라가, 그다음 모두가 친다. 그라치엘라가 일어나 부엌으로 간다. 주파 잉글레제를 들고 돌아온다."),
(G, "Seduti. Nessuno si alza prima del dolce. Anche se è venerdì.", "앉아. 디저트 전엔 아무도 안 일어나. 금요일이라도."),

("#", "Scena 3 — Ore 22.40. Il cortile di casa Corsini, accanto alle macchine.", "장면 3 — 오후 10시 40분. 코르시니 가 마당, 차들 옆."),
(None, "Fa freddo. Le finestre della cucina sono ancora accese: Graziella e Chiara lavano i piatti, Giulia asciuga. Matteo e Filippo sono fuori, appoggiati alla macchina di Filippo. Matteo ha le mani in tasca.", "춥다. 부엌 창문엔 아직 불이 켜져 있다. 그라치엘라와 키아라가 설거지를 하고 줄리아가 그릇을 닦는다. 마테오와 필리포는 밖에서 필리포의 차에 기대어 있다. 마테오는 주머니에 손을 넣고 있다."),
(M, "Da quando lo sapevi?", "언제부터 알았어?"),
(F, "Da agosto. Dal giorno che tu sei uscito da questa casa sbattendo la porta, e io sono rimasto a tavola con la mamma.", "8월부터. 네가 문을 쾅 닫고 이 집을 나간 날, 내가 엄마랑 식탁에 남아 있던 날부터."),
(M, "Ero arrabbiato con te.", "그땐 형한테 화가 나 있었어."),
(F, "Lo so. E io ho pensato: ecco, lui esce e io resto. Sempre così. Poi ho pensato: e se fosse questo il mio mestiere?", "알아. 그리고 생각했지. 봐라, 쟤는 나가고 나는 남는다. 늘 그래. 그러다 생각했어. 이게 내 일이라면?"),
(M, "Fili, in fondo tu hai sempre voluto essere il babbo.", "형, 결국 형은 늘 아빠가 되고 싶었잖아."),
(F, "In fondo sì. Ma il babbo faceva due mestieri, e ne amava uno solo. Me l'ha detto Renzo stamattina. Io non voglio fare due mestieri.", "결국은 그렇지. 그런데 아빠는 일을 두 가지 하면서 하나만 사랑했대. 오늘 아침에 렌초가 그러더라. 나는 일을 두 가지 하고 싶지 않아."),
(M, "E se fra due anni ti penti? Se ti svegli e pensi « dovevo farlo io »?", "그런데 2년 뒤에 후회하면? 자다 깨서 '내가 했어야 했는데' 하면?"),
(F, "Allora te lo dico. A tavola, la domenica. Come c'è scritto nelle premesse.", "그럼 너한테 말할게. 일요일 식탁에서. 전문에 적혀 있는 대로."),
(M, "E io ti ascolterò?", "그럼 나는 들을까?"),
(F, "Prima del dolce, sì. Dopo, non garantisco.", "디저트 전이면 들을 거야. 그다음은 장담 못 하고."),
(M, "(ride) Sai qual è la cosa che mi fa più paura? Non le banche. Non la Maison. Lunedì ventinove, quando entro in laboratorio e Marisa mi chiama « dottore ».", "(웃으며) 나 뭐가 제일 무서운지 알아? 은행도 아니고 메종도 아니야. 29일 월요일에 공방에 들어갔는데 마리사가 나를 '사장님'이라고 부를 때."),
(F, "Marisa ti chiamerà Matteo, come sempre. È Renzo che ti chiamerà « dottore », per farti arrabbiare.", "마리사는 늘 그렇듯 마테오라고 부를 거야. '사장님'이라고 부르는 건 렌초겠지. 너 약 올리려고."),
(M, "Fili. Grazie.", "형. 고마워."),
(F, "Non ringraziarmi. Ringrazia il dito che hai tolto dal tasto. (pausa) E un'altra cosa.", "고마워하지 마. 버튼에서 뗀 네 손가락한테 고마워해. (잠시 뒤) 그리고 하나 더."),
(M, "Dimmi.", "말해."),
(F, "Il primo anno, quando parti, dimmi sempre dove vai. Non per controllarti. Per tenere la porta dalla parte giusta.", "첫해엔 떠날 때마다 어디 가는지 꼭 말해 줘. 감시하려는 게 아니야. 문을 맞는 쪽으로 열어 두려고."),
(M, "Promesso. La prima è Dubai, a gennaio. Poi Seul.", "약속할게. 첫 번째는 1월에 두바이. 그다음 서울."),
(F, "Lo so. È nel budget. Riga quarantadue.", "알아. 예산에 있어. 42번째 줄."),
(None, "La porta della cucina si apre. Giulia esce con due fette di torta avvolte nel tovagliolo.", "부엌 문이 열린다. 줄리아가 냅킨에 싼 케이크 두 조각을 들고 나온다."),
(GI, "La nonna dice che il presidente e l'amministratore delegato si sono alzati prima del dolce. E che questa è la vostra multa.", "할머니가 그러는데, 회장이랑 대표이사가 디저트 전에 일어났대. 그리고 이게 벌금이래."),
(F, "Una multa di zuppa inglese. Accettiamo.", "주파 잉글레제 벌금이라. 받아들이지."),
(GI, "Papà, ti posso dire una cosa? Stasera, quando leggevi, ti tremava la voce.", "아빠, 하나 말해도 돼? 오늘 밤에 아빠가 읽을 때 목소리가 떨렸어."),
(F, "Si vedeva tanto?", "그렇게 티 났어?"),
(GI, "Solo a me. E alla nonna. E alla zia. (pausa) E allo zio.", "나한테만. 그리고 할머니한테. 그리고 고모한테. (잠시 뒤) 그리고 삼촌한테."),
(M, "Cioè a tutti.", "그러니까 다한테."),
(GI, "Cioè a tutti. Ma era bello. Ho fatto una foto al verbale, di nascosto.", "그러니까 다한테. 그래도 멋있었어. 의사록 사진 몰래 한 장 찍었어."),
(F, "(prende la torta) Mandamela. Ma non metterla su Instagram.", "(케이크를 받으며) 나한테 보내 줘. 인스타그램엔 올리지 말고."),
(GI, "Lo sapevo che dicevi così. Infatti l'ho già mandata alla chat di famiglia.", "그렇게 말할 줄 알았어. 그래서 이미 가족 단톡방에 보냈지."),
(M, "(guarda il telefono) La nonna ha già risposto.", "(휴대폰을 보며) 할머니가 벌써 답했어."),
(F, "Che cosa ha scritto?", "뭐라고 썼는데?"),
(M, "« Bravi. Adesso a letto, tutti e due. Il presidente ha le occhiaie. »", "'잘했다. 이제 둘 다 자러 가. 회장 다크서클 생겼다.'"),
(F, "(ride) Renzo e la mamma si sono messi d'accordo.", "(웃으며) 렌초랑 엄마가 짰네."),
]

